from itertools import permutations

def reachable(p):
    n=len(p)
    from collections import deque
    start=(1<<n)-1
    vis={start}
    q=deque([start])
    while q:
        m=q.popleft()
        bits=[i for i in range(n) if m>>i&1]
        for k in bits:
            nm=m
            for i in bits:
                if i==k: continue
                if (i<k and p[i]<p[k]) or (i>k and p[i]>p[k]):
                    nm &= ~(1<<i)
            if nm not in vis:
                vis.add(nm);q.append(nm)
    return vis

