import sys
sys.setrecursionlimit(1_000_000)

MOD = 998244353


def main() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    N = int(next(it))
    M = int(next(it))
    A = [int(next(it)) - 1 for _ in range(N)]

    g = [[] for _ in range(N)]
    rg = [[] for _ in range(N)]
    for i, to in enumerate(A):
        g[i].append(to)
        rg[to].append(i)

    # Kosaraju: find SCCs
    used = [False] * N
    order = []

    def dfs1(v: int) -> None:
        used[v] = True
        for to in g[v]:
            if not used[to]:
                dfs1(to)
        order.append(v)

    for v in range(N):
        if not used[v]:
            dfs1(v)

    comp = [-1] * N
    comps = []

    def dfs2(v: int, cid: int) -> None:
        comp[v] = cid
        comps[cid].append(v)
        for to in rg[v]:
            if comp[to] == -1:
                dfs2(to, cid)

    cid = 0
    for v in reversed(order):
        if comp[v] == -1:
            comps.append([])
            dfs2(v, cid)
            cid += 1

    K = cid

    # Condensation graph is a forest directed toward roots (cycle SCCs)
    parent = [-1] * K  # outgoing edge of SCC in condensation
    children = [[] for _ in range(K)]

    for v in range(N):
        c1 = comp[v]
        c2 = comp[A[v]]
        if c1 != c2:
            parent[c1] = c2

    for c in range(K):
        p = parent[c]
        if p != -1:
            children[p].append(c)

    roots = [c for c in range(K) if parent[c] == -1]

    # DP over SCC-forest
    # f[u][x] = ways in subtree of u with value(u) = x
    # pref[u][x] = sum_{t<=x} f[u][t]
    f = [None] * K
    pref = [None] * K

    def solve(u: int) -> None:
        for ch in children[u]:
            solve(ch)

        fu = [0] * (M + 1)
        if not children[u]:
            for x in range(1, M + 1):
                fu[x] = 1
        else:
            for x in range(1, M + 1):
                val = 1
                for ch in children[u]:
                    val = (val * pref[ch][x]) % MOD
                fu[x] = val

        pu = [0] * (M + 1)
        s = 0
        for x in range(1, M + 1):
            s += fu[x]
            if s >= MOD:
                s -= MOD
            pu[x] = s

        f[u] = fu
        pref[u] = pu

    ans = 1
    for r in roots:
        solve(r)
        ans = (ans * pref[r][M]) % MOD

    print(ans)


if __name__ == "__main__":
    main()

