import sys
import heapq

def main():
    input = sys.stdin.readline
    N, M, X = map(int, input().split())
    g = [[] for _ in range(N + 1)]
    rg = [[] for _ in range(N + 1)]
    for _ in range(M):
        u, v = map(int, input().split())
        g[u].append(v)
        rg[v].append(u)

    INF = 10**30
    dist0 = [INF] * (N + 1)  # parity 0 (original orientation)
    dist1 = [INF] * (N + 1)  # parity 1 (reversed orientation)

    dist0[1] = 0
    h = [(0, 1, 0)]  # (dist, vertex, parity)

    while h:
        d, v, p = heapq.heappop(h)
        if p == 0:
            if d != dist0[v]:
                continue
            nd = d + X
            if nd < dist1[v]:
                dist1[v] = nd
                heapq.heappush(h, (nd, v, 1))
            nd = d + 1
            for to in g[v]:
                if nd < dist0[to]:
                    dist0[to] = nd
                    heapq.heappush(h, (nd, to, 0))
        else:
            if d != dist1[v]:
                continue
            nd = d + X
            if nd < dist0[v]:
                dist0[v] = nd
                heapq.heappush(h, (nd, v, 0))
            nd = d + 1
            for to in rg[v]:
                if nd < dist1[to]:
                    dist1[to] = nd
                    heapq.heappush(h, (nd, to, 1))

    ans = dist0[N] if dist0[N] < dist1[N] else dist1[N]
    print(ans)

if __name__ == "__main__":
    main()

