import sys

MOD = 998244353


def main() -> None:
    data = list(map(int, sys.stdin.read().split()))
    if not data:
        return

    N = data[0]
    A = data[1:]

    # Smallest prime factor up to 1000
    MAXA = 1000
    spf = list(range(MAXA + 1))
    for i in range(2, int(MAXA ** 0.5) + 1):
        if spf[i] == i:
            for j in range(i * i, MAXA + 1, i):
                if spf[j] == j:
                    spf[j] = i

    # exps[p][i] = v_p(A_i)
    exps = {}
    for i, a in enumerate(A):
        x = a
        while x > 1:
            p = spf[x]
            c = 0
            while x % p == 0:
                x //= p
                c += 1
            if p not in exps:
                exps[p] = [0] * (N - 1)
            exps[p][i] = c

    ans = 1

    for p, d in exps.items():
        D = sum(d)
        if D == 0:
            continue

        # p^v for v=0..D
        powp = [1] * (D + 1)
        for v in range(1, D + 1):
            powp[v] = (powp[v - 1] * p) % MOD

        # DP over x_i value and whether we've seen 0 already
        no = [0] * (D + 1)   # not seen 0 yet
        yes = [0] * (D + 1)  # seen 0

        # initialize x_1
        for v in range(D + 1):
            w = powp[v]  # contributes p^{x_1}
            if v == 0:
                yes[v] = w
            else:
                no[v] = w

        # transitions for i=1..N-1 with |x_i - x_{i+1}| = d_i
        for step in d:
            nno = [0] * (D + 1)
            nyes = [0] * (D + 1)

            if step == 0:
                for v in range(D + 1):
                    mul = powp[v]  # contributes p^{x_{i+1}}
                    a = no[v]
                    if a:
                        nno[v] = (nno[v] + a * mul) % MOD
                    b = yes[v]
                    if b:
                        nyes[v] = (nyes[v] + b * mul) % MOD
            else:
                s = step
                for v in range(D + 1):
                    a = no[v]
                    b = yes[v]
                    if not a and not b:
                        continue

                    w = v + s
                    if w <= D:
                        mul = powp[w]
                        if a:
                            nno[w] = (nno[w] + a * mul) % MOD
                        if b:
                            nyes[w] = (nyes[w] + b * mul) % MOD

                    w = v - s
                    if w >= 0:
                        mul = powp[w]
                        if a:
                            if w == 0:
                                nyes[w] = (nyes[w] + a * mul) % MOD
                            else:
                                nno[w] = (nno[w] + a * mul) % MOD
                        if b:
                            nyes[w] = (nyes[w] + b * mul) % MOD

            no, yes = nno, nyes

        Fp = sum(yes) % MOD
        ans = (ans * Fp) % MOD

    print(ans)


if __name__ == "__main__":
    main()

