from typing import List

class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        m = len(conflictingPairs)
        by_y = [[] for _ in range(n + 1)]
        for i, (a, b) in enumerate(conflictingPairs):
            x, y = (a, b) if a < b else (b, a)
            by_y[y].append((x, i))

        cnt = [0] * (n + 1)          # cnt[x] = how many inserted pairs have smaller endpoint x
        sole_id = [-1] * (n + 1)     # valid only when cnt[x] == 1
        gain = [0] * m

        vmax = 0     # current largest x with cnt[x] > 0
        second = 0   # current largest x < vmax with cnt[x] > 0

        total = 0

        for r in range(1, n + 1):
            for x, pid in by_y[r]:
                if cnt[x] == 0:
                    cnt[x] = 1
                    sole_id[x] = pid
                    if x > vmax:
                        second = vmax
                        vmax = x
                    elif x > second and x < vmax:
                        second = x
                else:
                    cnt[x] += 1
                    # sole_id[x] no longer needed when cnt[x] > 1

            total += r - vmax

            if vmax > 0 and cnt[vmax] == 1:
                pid = sole_id[vmax]
                gain[pid] += vmax - second

        best_gain = max(gain) if gain else 0
        return total + best_gain

