import sys


def min_cost(A, P, B, Q, m):
    if m <= 0:
        return 0
    INF = 10**30
    ans = INF

    # If S is at least as cost-efficient as T, keep t small (0..A-1).
    if A * Q >= B * P:
        for t in range(A):
            need = m - B * t
            s = 0 if need <= 0 else (need + A - 1) // A
            cost = s * P + t * Q
            if cost < ans:
                ans = cost
    else:
        # T is more cost-efficient: keep s small (0..B-1).
        for s in range(B):
            need = m - A * s
            t = 0 if need <= 0 else (need + B - 1) // B
            cost = s * P + t * Q
            if cost < ans:
                ans = cost

    return ans


def main():
    input = sys.stdin.readline
