        total = 0
        for A, P, B, Q in procs:
            total += min_cost(A, P, B, Q, cap)
            if total > X:
                return False
        return total <= X

    lo, hi = 0, 1
    while feasible(hi):
        hi *= 2

    while hi - lo > 1:
        mid = (lo + hi) // 2
        if feasible(mid):
            lo = mid
        else:
            hi = mid

    print(lo)


