class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 10**9 + 7
        n = len(s)

        # steps[t] = operations needed to reduce t to 1 by repeated popcount.
        # steps[1] = 0.
        steps = [0] * (n + 1)
        for t in range(2, n + 1):
            steps[t] = 1 + steps[t.bit_count()]

        # For x > 1, one operation makes it popcount(x)=t,
        # then it needs steps[t] more. So total <= k iff steps[t] <= k-1.
        limit = k - 1
        good = [False] * (n + 1)
        for t in range(1, n + 1):
            if steps[t] <= limit:
                good[t] = True

        # Binomial coefficients C[i][j] modulo MOD.
        C = [[0] * (n + 1) for _ in range(n + 1)]
        for i in range(n + 1):
            C[i][0] = 1
            C[i][i] = 1
            for j in range(1, i):
                C[i][j] = (C[i - 1][j - 1] + C[i - 1][j]) % MOD

        def count_less_with_ones(target_ones: int) -> int:
            """Count y in [0, int(s,2)-1] with popcount(y) = target_ones."""
            used = 0
            ans = 0
            for i, ch in enumerate(s):
                if ch == '1':
                    rem = n - i - 1
                    need = target_ones - used
                    if 0 <= need <= rem:
                        ans = (ans + C[rem][need]) % MOD
                    used += 1
                    if used > target_ones:
                        break
            return ans

        ans = 0
        for ones in range(1, n + 1):
            if good[ones]:
                ans = (ans + count_less_with_ones(ones)) % MOD

        return ans

