class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        nlen=len(s)
        # precompute reduce steps for t up to nlen
        steps=[0]*(nlen+1)
        for i in range(2,nlen+1):
            steps[i]=1+steps[i.bit_count()]
        eligible=[False]*(nlen+1)
        lim=k-1
        for t in range(1,nlen+1):
            if steps[t]<=lim:
                eligible[t]=True

        # combinations
        C=[[0]*(nlen+1) for _ in range(nlen+1)]
        for i in range(nlen+1):
            C[i][0]=C[i][i]=1
            for j in range(1,i):
                C[i][j]=(C[i-1][j-1]+C[i-1][j])%MOD

        def count_with_ones(target):
            used=0
            ans=0
            for i,ch in enumerate(s):
                if ch=='1':
                    rem=nlen-i-1
                    need=target-used
                    if 0<=need<=rem:
                        ans=(ans + C[rem][need])%MOD
                    used+=1
                    if used>target:
                        break
            return ans

        ans=0
        for t in range(1,nlen+1):
            if eligible[t]:
                ans=(ans+count_with_ones(t))%MOD
        return ans

