import sys


def is_bad(a, b):
    s1, t1 = a
    s2, t2 = b
    l1, r1 = (s1, t1) if s1 < t1 else (t1, s1)
    l2, r2 = (s2, t2) if s2 < t2 else (t2, s2)
    sign1 = 1 if s1 < t1 else -1
    sign2 = 1 if s2 < t2 else -1

    eq = (s1 == s2) or (s1 == t2) or (t1 == s2) or (t1 == t2)

    lt = False  # c1 < c2 forced
    gt = False  # c1 > c2 forced

    # endpoints of b inside interval of a
    if l1 < s2 < r1 or l1 < t2 < r1:
        if sign1 == 1:
            lt = True
        else:
            gt = True

    # endpoints of a inside interval of b
    if l2 < s1 < r2 or l2 < t1 < r2:
        if sign2 == 1:
            gt = True
        else:
            lt = True

    # opposite directions + overlap gives additional inequality
    if sign1 != sign2 and max(l1, l2) < min(r1, r2):
        if sign1 == 1:
            lt = True
        else:
            gt = True

    if eq and (lt or gt):
        return True
    if lt and gt:
        return True
    return False


def main():
    input = sys.stdin.readline
    N, M, Q = map(int, input().split())
    people = [tuple(map(int, input().split())) for _ in range(M)]

    # b[j] = max i<j such that (i,j) is bad
    b = [0] * M

    # NOTE: O(M^2), not suitable for worst-case constraints.
    for j in range(M):
        sjtj = people[j]
        mx = 0
        for i in range(j):
            if is_bad(people[i], sjtj):
                mx = i + 1  # 1-indexed
        b[j] = mx

    # segment tree for range max on b
    size = 1
    while size < M:
        size <<= 1
    seg = [0] * (2 * size)
    for i in range(M):
        seg[size + i] = b[i]
    for i in range(size - 1, 0, -1):
        seg[i] = seg[i << 1] if seg[i << 1] > seg[i << 1 | 1] else seg[i << 1 | 1]

    def range_max(l, r):
        # 0-indexed inclusive
        l += size
        r += size
        ans = 0
        while l <= r:
            if l & 1:
                if seg[l] > ans:
                    ans = seg[l]
                l += 1
            if not (r & 1):
                if seg[r] > ans:
                    ans = seg[r]
                r -= 1
            l >>= 1
            r >>= 1
        return ans

    out = []
    for _ in range(Q):
        L, R = map(int, input().split())
        L -= 1
        R -= 1
        mx = range_max(L, R)
        if mx >= L + 1:
            out.append("No")
        else:
            out.append("Yes")

    print("\n".join(out))


if __name__ == "__main__":
    main()

