MAXB = 100
STOP_D = 61

def is_mountain_from_residue(r: int) -> bool:
    lb = r & -r
    return (r & (lb << 1)) != 0  # odd part mod 4 == 3

def mountain_classes_for_h(x: int, d: int):
    classes = []
    for t in range(MAXB):
        mpow = t + 2
        target = 3 << t
        if d <= mpow:
            m = mpow - d
            rhs = target - x
            if rhs & ((1 << d) - 1):
                continue
            r = (rhs >> d) & ((1 << m) - 1 if m > 0 else 0)
            classes.append((m, r))
        else:
            mod = 1 << mpow
            if (x - target) % mod == 0:
                classes.append((0, 0))
    return classes

def class_intersection(c1, c2):
    m1, r1 = c1
    m2, r2 = c2
    m = min(m1, m2)
    mask = (1 << m) - 1 if m > 0 else 0
    if ((r1 - r2) & mask) != 0:
        return None
    return (max(m1, m2), r1 if m1 >= m2 else r2)

def class_has_solution(m, r, L, exclude_zero):
    # h in [0, 2^L), h ≡ r (mod 2^m)
    if L >= m:
        if not exclude_zero:
            return True
        if r != 0:
            return True
        return L > m  # r=0, need another multiple of 2^m besides 0
    else:
        h = r & ((1 << L) - 1)
