import sys, math

def icbrt(n: int) -> int:
    lo, hi = 0, 1
    while hi ** 3 <= n:
        hi *= 2
    while hi - lo > 1:
        mid = (lo + hi) // 2
        if mid ** 3 <= n:
            lo = mid
        else:
            hi = mid
    return lo

def main():
    N_line = sys.stdin.readline().strip()
    if not N_line:
        return
    N = int(N_line)

    limit = icbrt(N)
    for d in range(1, limit + 1):
        if N % d != 0:
            continue

        m = N // d
        # From x = y + d:
        # N = d * (3y^2 + 3dy + d^2) = d * m
        # => 3y^2 + 3dy + (d^2 - m) = 0
        # Discriminant D = (3d)^2 - 4*3*(d^2 - m) = 12m - 3d^2
        D = 12 * m - 3 * d * d
        if D < 0:
            continue

        s = math.isqrt(D)
        if s * s != D:
            continue

        num = -3 * d + s
        if num <= 0 or num % 6 != 0:
            continue

