from array import array

class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n, m = len(grid), len(grid[0])
        nm = n * m

        # 0: down-right, 1: down-left, 2: up-left, 3: up-right
        dirs = [(1, 1), (1, -1), (-1, -1), (-1, 1)]
        cw = [1, 2, 3, 0]  # clockwise 90-degree turn mapping

        # noturn[d] = (arr_expect0, arr_expect2)
        # arr_expectX[idx] = longest alternating (2,0,2,...) segment length
        # starting at idx when current expected value is X (0 or 2), with no turn.
        noturn = [None] * 4

        for d, (dx, dy) in enumerate(dirs):
            expect0 = array('H', [0]) * nm
            expect2 = array('H', [0]) * nm

            ir = range(n - 1, -1, -1) if dx == 1 else range(n)
            jr = range(m - 1, -1, -1) if dy == 1 else range(m)

            for i in ir:
                ni = i + dx
                base = i * m
                for j in jr:
                    idx = base + j
                    v = grid[i][j]
                    nj = j + dy

                    if 0 <= ni < n and 0 <= nj < m:
                        nidx = ni * m + nj
                        if v == 0:
                            expect0[idx] = 1 + expect2[nidx]
                        elif v == 2:
                            expect2[idx] = 1 + expect0[nidx]
                    else:
                        if v == 0:
                            expect0[idx] = 1
                        elif v == 2:
                            expect2[idx] = 1

            noturn[d] = (expect0, expect2)

        # turn[d] = (arr_expect0, arr_expect2)
        # same as above, but we may use at most one clockwise turn from current direction.
        turn = [None] * 4

        for d, (dx, dy) in enumerate(dirs):
            d2 = cw[d]
            dx2, dy2 = dirs[d2]
            n0_d2, n2_d2 = noturn[d2]

            t0 = array('H', [0]) * nm
            t2 = array('H', [0]) * nm

            ir = range(n - 1, -1, -1) if dx == 1 else range(n)
            jr = range(m - 1, -1, -1) if dy == 1 else range(m)

            for i in ir:
                ni = i + dx
                ti = i + dx2
                base = i * m
                for j in jr:
                    idx = base + j
                    v = grid[i][j]

                    # Option 1: continue straight (still can turn later)
                    best_straight = 0
                    nj = j + dy
                    if 0 <= ni < n and 0 <= nj < m:
                        nidx = ni * m + nj
                        if v == 0:
                            best_straight = t2[nidx]
                        elif v == 2:
                            best_straight = t0[nidx]

                    # Option 2: turn now clockwise and continue with no further turns
                    best_turn_now = 0
                    tj = j + dy2
                    if 0 <= ti < n and 0 <= tj < m:
                        tidx = ti * m + tj
                        if v == 0:
                            best_turn_now = n2_d2[tidx]
                        elif v == 2:
                            best_turn_now = n0_d2[tidx]

                    best_next = best_straight if best_straight >= best_turn_now else best_turn_now

                    if v == 0:
                        t0[idx] = 1 + best_next
                    elif v == 2:
                        t2[idx] = 1 + best_next

            turn[d] = (t0, t2)

        ans = 0

        # Start must be 1. After that, expected value is 2.
        for i in range(n):
            for j in range(m):
                if grid[i][j] != 1:
                    continue

                if ans < 1:
                    ans = 1

                for d, (dx, dy) in enumerate(dirs):
                    ni, nj = i + dx, j + dy
                    if 0 <= ni < n and 0 <= nj < m:
                        nidx = ni * m + nj
                        cand = 1 + turn[d][1][nidx]  # next expected is 2
                        if cand > ans:
                            ans = cand

        return ans

