class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        m = (n + 1) // 2

        # pow10[i] = 10^i mod k
        pow10 = [0] * n
        pow10[0] = 1 % k
        for i in range(1, n):
            pow10[i] = (pow10[i - 1] * 10) % k

        # Each free digit in the left half contributes to two mirrored positions
        coef = [0] * m
        for t in range(m):
            r = n - 1 - t
            if t == r:  # middle digit when n is odd
                coef[t] = pow10[t]
            else:
                coef[t] = (pow10[t] + pow10[r]) % k

        # can[pos][rem] = whether positions pos..m-1 can sum to 'rem' modulo k
        can = [[False] * k for _ in range(m + 1)]
        can[m][0] = True

        for pos in range(m - 1, -1, -1):
            c = coef[pos]
            nxt = can[pos + 1]
            cur = can[pos]
            for rem in range(k):
                ok = False
                for d in range(10):
                    if nxt[(rem - d * c) % k]:
                        ok = True
                        break
                cur[rem] = ok

        # Greedily build the lexicographically largest left half
        left = []
        rem = 0  # remainder needed from current suffix

        for pos in range(m):
            c = coef[pos]
            low = 1 if pos == 0 else 0  # no leading zero
            for d in range(9, low - 1, -1):
                nxt_rem = (rem - d * c) % k
                if can[pos + 1][nxt_rem]:
                    left.append(str(d))
                    rem = nxt_rem
                    break

        if n % 2 == 0:
            return ''.join(left + left[::-1])
        return ''.join(left + left[:-1][::-1])

