from typing import List

class Solution:
    def maximizeSumOfWeights(self, edges: List[List[int]], k: int) -> int:
        n = len(edges) + 1
        adj = [[] for _ in range(n)]
        for u, v, w in edges:
            adj[u].append((v, w))
            adj[v].append((u, w))

        parent = [-1] * n
        order = [0]
        parent[0] = 0
        for u in order:
            for v, _ in adj[u]:
                if v == parent[u]:
                    continue
                parent[v] = u
                order.append(v)

        dp0 = [0] * n  # max sum in subtree if edge to parent is not kept
        dp1 = [0] * n  # max sum in subtree if edge to parent is kept

        for u in reversed(order):
            base = 0
            gains = []
            for v, w in adj[u]:
                if v == parent[u]:
                    continue
                base += dp0[v]
                gains.append(w + dp1[v] - dp0[v])

            gains.sort(reverse=True)

            total0 = base
            for g in gains[:k]:
                if g > 0:
                    total0 += g
                else:
                    break
            dp0[u] = total0

            cap1 = k - 1
            total1 = base
            if cap1 > 0:
                for g in gains[:cap1]:
                    if g > 0:
                        total1 += g
                    else:
                        break
            dp1[u] = total1

        return dp0[0]

