import random, heapq, functools

def algo(a):
    n=len(a)
    def compute_prefix(vals):
        low=[]; high=[]; sL=0; sH=0
        pref=[0]*(len(vals)+1)
        for i,x in enumerate(vals,1):
            if not low or x<=-low[0]:
                heapq.heappush(low,-x); sL+=x
            else:
                heapq.heappush(high,x); sH+=x
            if len(low)>len(high)+1:
                v=-heapq.heappop(low); sL-=v; heapq.heappush(high,v); sH+=v
            elif len(low)<len(high):
                v=heapq.heappop(high); sH-=v; heapq.heappush(low,-v); sL+=v
            if i%2==0:
                pref[i]=sH-sL
        return pref
    pref=compute_prefix(a)
    if n%2==0:
        return pref[n]
    rev=a[::-1]
    suf_rev=compute_prefix(rev)
    # map
    suf=[0]*(n+2)
    for i in range(1,n+1):
        L=n-i+1
        if L%2==0:
            suf[i]=suf_rev[L]
    ans=0
    for k in range(1,n+1,2):
        ans=max(ans,pref[k-1]+suf[k+1])
    return ans

