    def kmp_occurrences(self, s: str, pat: str):
        """Return all start indices where pat occurs in s (pat non-empty)."""
        n, m = len(s), len(pat)
        lps = [0] * m

        j = 0
        for i in range(1, m):
            while j > 0 and pat[i] != pat[j]:
                j = lps[j - 1]
            if pat[i] == pat[j]:
                j += 1
                lps[i] = j

        occ = []
        j = 0
        for i, ch in enumerate(s):
            while j > 0 and ch != pat[j]:
                j = lps[j - 1]
            if ch == pat[j]:
                j += 1
                if j == m:
                    occ.append(i - m + 1)
                    j = lps[j - 1]
        return occ

    def build_next_array(self, n: int, occ, token_len: int):
        """next_pos[i] = smallest occurrence start >= i, else n+1."""
        INF = n + 1
        mark = [False] * (n + 1)
        for st in occ:
            if st <= n - token_len:
                mark[st] = True

        next_pos = [INF] * (n + 1)
        cur = INF
        for i in range(n, -1, -1):
            if mark[i]:
                cur = i
            next_pos[i] = cur
        return next_pos

    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        n = len(s)
        a, b, c = p.split('*')  # exactly two '*'
        la, lb, lc = len(a), len(b), len(c)

        # Possible starts for segment a
        if la == 0:
            occ_a = range(n + 1)  # empty token can start at any boundary
        else:
            occ_a = self.kmp_occurrences(s, a)

        # Precompute next start for b and c (if non-empty)
        next_b = None
        if lb > 0:
            occ_b = self.kmp_occurrences(s, b)
            next_b = self.build_next_array(n, occ_b, lb)

        next_c = None
        if lc > 0:
            occ_c = self.kmp_occurrences(s, c)
            next_c = self.build_next_array(n, occ_c, lc)

        INF = 10**18
        ans = INF

        for sa in occ_a:
            pos_after_a = sa + la
            if pos_after_a > n:
                continue

            sb = pos_after_a if lb == 0 else next_b[pos_after_a]
            if sb > n:
                continue

            pos_after_b = sb + lb
            if pos_after_b > n:
                continue

            sc = pos_after_b if lc == 0 else next_c[pos_after_b]
            if sc > n:
                continue

            end_pos = sc + lc
            if end_pos <= n:
                cur_len = end_pos - sa
                if cur_len < ans:
                    ans = cur_len

        return -1 if ans == INF else ans

