import random, numpy as np

def exact(N,M):
    n=1+N*M
    vid=lambda a,d:1+a*M+(d-1)
    adj=[[] for _ in range(n)]
    for a in range(N):
        prev=0
        for d in range(1,M+1):
            v=vid(a,d)
            adj[prev].append(v);adj[v].append(prev)
            prev=v
    full=(1<<n)-1
    states=[];idx={}
    for mask in range(1<<n):
      if not(mask&1): continue
      for pos in range(n):
        if not(mask>>pos&1):continue
        if mask==full: continue
        idx[(pos,mask)]=len(states);states.append((pos,mask))
    m=len(states)
    A=np.zeros((m,m));b=np.ones(m)
    for i,(pos,mask) in enumerate(states):
      A[i,i]=1
      deg=len(adj[pos])
      for to in adj[pos]:
        nmask=mask| (1<<to)
        if nmask==full: continue
        A[i,idx[(to,nmask)]]-=1/deg
    x=np.linalg.solve(A,b)
    return x[idx[(0,1)]]

