import sys

def solve_case(N, A, B):
    p = [i for i, c in enumerate(A) if c == '1']
    q = [i for i, c in enumerate(B) if c == '1']
    m = len(p)
    r = len(q)
    if r > m:
        return -1

    def can(k: int) -> bool:
        prev = [False] * r
        if abs(p[0] - q[0]) <= k:
            prev[0] = True
        for i in range(1, m):
            cur = [False] * r
            d = p[i] - p[i - 1]
            pi = p[i]
            for l, ok in enumerate(prev):
                if not ok:
                    continue
                if abs(pi - q[l]) <= k:
                    cur[l] = True
                j = l + 1
                if j < r and q[j] - q[l] <= d and abs(pi - q[j]) <= k:
                    cur[j] = True
            prev = cur
            if not any(prev):
                return False
        return prev[r - 1]

    lo, hi = 0, N
    if not can(hi):
        return -1
    while lo < hi:
        mid = (lo + hi) // 2
        if can(mid):
            hi = mid
        else:
            lo = mid + 1
    return lo


