import itertools,math

def bfs(A):
    n=len(A)
    st=tuple(int(c) for c in A)
    dist={st:0}
    q=deque([st])
    while q:
        s=q.popleft();d=dist[s]
        for i in range(n):
            ns=[0]*n
            for j,c in enumerate(s):
                if c:
                    nj=j-1 if i<j else j+1 if i>j else j
                    ns[nj]+=c
            ns=tuple(ns)
            if ns not in dist:
                dist[ns]=d+1;q.append(ns)
    return dist

def support(s):
    return ''.join('1' if x>0 else '0' for x in s)

def pop(s): return s.count('1')
def span(s):
    idx=[i for i,ch in enumerate(s) if ch=='1']
    return idx[-1]-idx[0]

def left(s):return s.find('1')
def right(s):return s.rfind('1')

