import sys

class Fenwick:
    def __init__(self, n):
        self.n = n
        self.bit = [0] * (n + 1)

    def add(self, i, x):
        while i <= self.n:
            self.bit[i] += x
            i += i & -i

    def kth(self, k):
        # Returns the smallest index idx such that prefix_sum(idx) >= k
        idx = 0
        step = 1 << (self.n.bit_length())
        while step:
            nxt = idx + step
            if nxt <= self.n and self.bit[nxt] < k:
                k -= self.bit[nxt]
                idx = nxt
            step >>= 1
        return idx + 1


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    n = data[0]
    p = data[1:1 + n]

    fw = Fenwick(n)
    for i in range(1, n + 1):
        fw.add(i, 1)  # mark all positions as empty

    ans = [0] * n

    # Process in reverse: place i into the P_i-th empty position
    for i in range(n, 0, -1):
        pos = fw.kth(p[i - 1])
        ans[pos - 1] = i
        fw.add(pos, -1)  # position is no longer empty

    print(*ans)


if __name__ == "__main__":
    main()

