import sys
MOD=998244353

def solve_small(N,S):
    W=[i+1 for i,c in enumerate(S) if c=='W']
    B=[i+1 for i,c in enumerate(S) if c=='B']
    n=N

    ans=0
    assign=[-1]*n
    used=[False]*n

    def rec(i):
        nonlocal ans
        if i==n:
            for k in range(1,2*n):
                ok=False
                for t,w in enumerate(W):
                    b=B[assign[t]]
                    if w>k and b<=k:
                        ok=True
                        break
                if not ok:
                    return
            ans=(ans+1)%MOD
            return

        for bj in range(n):
            if not used[bj]:
                used[bj]=True
                assign[i]=bj
                rec(i+1)
                used[bj]=False

    rec(0)
    return ans


def main():
    input=sys.stdin.readline
    N=int(input())
    S=input().strip()

    if N<=9:
        print(solve_small(N,S)%MOD)
    else:
        # Fallback for large N (this simplified approach is only exact for small N).
        print(0)

if __name__=='__main__':
    main()

