import sys
from collections import deque

INF = 10**18

class MinCostMaxFlow:
    def __init__(self, n):
        self.n = n
        self.g = [[] for _ in range(n)]

    def add_edge(self, fr, to, cap, cost):
        self.g[fr].append([to, cap, cost, len(self.g[to])])
        self.g[to].append([fr, 0, -cost, len(self.g[fr]) - 1])

    def min_cost_flow(self, s, t, f):
        n = self.n
        res = 0
        h = [0] * n  # potential
        prevv = [0] * n
        preve = [0] * n

        import heapq
        while f > 0:
            dist = [INF] * n
            dist[s] = 0
            pq = [(0, s)]
            while pq:
                d, v = heapq.heappop(pq)
                if dist[v] != d:
                    continue
                for i, e in enumerate(self.g[v]):
                    to, cap, cost, rev = e
                    if cap <= 0:
                        continue
                    nd = d + cost + h[v] - h[to]
                    if nd < dist[to]:
                        dist[to] = nd
                        prevv[to] = v
                        preve[to] = i
                        heapq.heappush(pq, (nd, to))
            if dist[t] == INF:
                return None
            for v in range(n):
                if dist[v] < INF:
                    h[v] += dist[v]

            d = f
            v = t
            while v != s:
                e = self.g[prevv[v]][preve[v]]
                d = min(d, e[1])
                v = prevv[v]
            f -= d
            res += d * h[t]
            v = t
            while v != s:
                e = self.g[prevv[v]][preve[v]]
                e[1] -= d
                rev = e[3]
                self.g[v][rev][1] += d
                v = prevv[v]
        return res

def main():
    input = sys.stdin.readline
    N, M, S, T = map(int, input().split())
    edges = [tuple(map(int, input().split())) for _ in range(M)]

    # Vertex splitting: in=2*(v-1), out=in+1
    def vin(v):
        return 2 * (v - 1)
    def vout(v):
        return 2 * (v - 1) + 1

    mcmf = MinCostMaxFlow(2 * N)

    for v in range(1, N + 1):
        cap = 2 if v == S or v == T else 1
        mcmf.add_edge(vin(v), vout(v), cap, 0)

    for u, v in edges:
        mcmf.add_edge(vout(u), vin(v), 1, 1)
        mcmf.add_edge(vout(v), vin(u), 1, 1)

    ans = mcmf.min_cost_flow(vout(S), vin(T), 2)
    if ans is None:
        print(-1)
    else:
        print(ans)

if __name__ == '__main__':
    main()

