from typing import List

class Solution:
    def maxEnergyBoost(self, energyDrinkA: List[int], energyDrinkB: List[int]) -> int:
        n = len(energyDrinkA)
        if n == 0:
            return 0

        # dpA_i1 = dpA[i-1], dpA_i2 = dpA[i-2]
        # dpB_i1 = dpB[i-1], dpB_i2 = dpB[i-2]
        dpA_i2 = energyDrinkA[0]
        dpB_i2 = energyDrinkB[0]

        if n == 1:
            return max(dpA_i2, dpB_i2)

        dpA_i1 = energyDrinkA[1] + dpA_i2
        dpB_i1 = energyDrinkB[1] + dpB_i2

        for i in range(2, n):
            curA = energyDrinkA[i] + max(dpA_i1, dpB_i2)
            curB = energyDrinkB[i] + max(dpB_i1, dpA_i2)

            dpA_i2, dpA_i1 = dpA_i1, curA
            dpB_i2, dpB_i1 = dpB_i1, curB

        return max(dpA_i1, dpB_i1)

