import sys
import math


def sieve(n: int):
    if n < 2:
        return []
    is_prime = bytearray(b"\x01") * (n + 1)
    is_prime[0:2] = b"\x00\x00"
    r = int(n**0.5)
    for i in range(2, r + 1):
        if is_prime[i]:
            start = i * i
            is_prime[start:n + 1:i] = b"\x00" * (((n - start) // i) + 1)
    return [i for i in range(2, n + 1) if is_prime[i]]


def main():
    N = int(sys.stdin.readline())

    M = math.isqrt(N)
    primes = sieve(M)

    # 1) n = p^8
    cnt_p8 = 0
    for p in primes:
        if p**8 <= N:
            cnt_p8 += 1
        else:
            break

    # 2) n = p^2 q^2 (p < q), equivalent to p*q <= sqrt(N)
    cnt_p2q2 = 0
    j = len(primes) - 1
    for i, p in enumerate(primes):
        while j > i and p * primes[j] > M:
            j -= 1
        if j <= i:
            break
        cnt_p2q2 += j - i

    print(cnt_p8 + cnt_p2q2)


if __name__ == "__main__":
    main()

