    cnt2 = 0
    j = len(primes) - 1
    for i, p in enumerate(primes):
        while j > i and p * primes[j] > M:
            j -= 1
        if j <= i:
            break
        cnt2 += (j - i)

    print(cnt1 + cnt2)

