import sys

def main():
    input = sys.stdin.readline
    N, Q = map(int, input().split())
    S = list(input().strip())

    def is_abc(i):
        return 0 <= i and i + 2 < N and S[i] == 'A' and S[i+1] == 'B' and S[i+2] == 'C'

    cnt = 0
    for i in range(N - 2):
        if is_abc(i):
            cnt += 1

    out = []
    for _ in range(Q):
        x, c = input().split()
        x = int(x) - 1

        # Remove contributions that may be affected by changing S[x]
        for i in (x - 2, x - 1, x):
            if is_abc(i):
                cnt -= 1

        S[x] = c

        # Add contributions after the update
        for i in (x - 2, x - 1, x):
            if is_abc(i):
                cnt += 1

        out.append(str(cnt))

    print('\n'.join(out))

if __name__ == '__main__':
    main()

