class Solution:
    def countPairs(self, nums: List[int]) -> int:
        def reachable_values(v: int):
            s = list(str(v))
            m = len(s)
            out = {v}  # zero operations allowed
            for i in range(m):
                for j in range(i + 1, m):
                    t = s[:]
                    t[i], t[j] = t[j], t[i]
                    out.add(int(''.join(t)))  # leading zeros naturally collapse in int()
            return out

        reachable = [reachable_values(x) for x in nums]

        ans = 0
        n = len(nums)
        for i in range(n):
            for j in range(i + 1, n):
                if nums[j] in reachable[i] or nums[i] in reachable[j]:
                    ans += 1
        return ans

def solve(R):
    RR=(2*R)*(2*R)
    b=R-1
    ans=0
    for a in range(R):
        u=2*a+1
        while b>=0 and u*u + (2*b+1)*(2*b+1) > RR:
            b-=1
        if b<0:
            break
        count_y=1+2*b
        mult_x=1 if a==0 else 2
        ans += mult_x*count_y
    return ans
