from typing import List


class LiChaoNode:
    __slots__ = ("l", "r", "line", "left", "right")

    def __init__(self, l: int, r: int):
        self.l = l
        self.r = r
        self.line = None  # (m, b)
        self.left = None
        self.right = None


class Solution:
    def findMaximumScore(self, nums: List[int]) -> int:
        n = len(nums)
        if n == 1:
            return 0

        def value(line, x: int) -> int:
            m, b = line
            return m * x + b

        root = LiChaoNode(0, n - 1)

        def add_line(node: LiChaoNode, new_line) -> None:
            l, r = node.l, node.r
            mid = (l + r) // 2

            if node.line is None:
                node.line = new_line
                return

            cur = node.line
            # Keep the better line at midpoint in node.line
            if value(new_line, mid) > value(cur, mid):
                node.line, new_line = new_line, node.line

            if l == r:
                return

            # If the remaining line can be better on left or right segment, recurse there.
            if value(new_line, l) > value(node.line, l):
                if node.left is None:
                    node.left = LiChaoNode(l, mid)
                add_line(node.left, new_line)
            elif value(new_line, r) > value(node.line, r):
                if node.right is None:
                    node.right = LiChaoNode(mid + 1, r)
                add_line(node.right, new_line)

        NEG_INF = -10**30

        def query(node: LiChaoNode, x: int) -> int:
            if node is None:
                return NEG_INF

            best = value(node.line, x) if node.line is not None else NEG_INF
            if node.l == node.r:
                return best

            mid = (node.l + node.r) // 2
            if x <= mid:
                child_best = query(node.left, x)
            else:
                child_best = query(node.right, x)
            return best if best > child_best else child_best

        # dp[0] = 0, line for i=0: y = nums[0] * x + (0 - 0*nums[0])
        add_line(root, (nums[0], 0))

        dp_j = 0
        for j in range(1, n):
            # dp[j] = max_i (dp[i] + (j-i)*nums[i])
            dp_j = query(root, j)
            # Add line for this j as future i:
            # dp[j] + (x-j)*nums[j] = nums[j]*x + (dp[j] - j*nums[j])
            add_line(root, (nums[j], dp_j - j * nums[j]))

        return dp_j

