from collections import Counter

class Solution:
    def getLargestOutlier(self, nums: List[int]) -> int:
        total = sum(nums)
        cnt = Counter(nums)

        ans = -10**18
        for outlier in nums:
            rem = total - outlier
            if rem % 2 != 0:
                continue

            sum_elem = rem // 2

            # Need a distinct index for the sum element.
            if cnt.get(sum_elem, 0) - (1 if sum_elem == outlier else 0) > 0:
                ans = max(ans, outlier)

        return ans

