class Solution:
    def minZeroArray(self, nums: List[int], queries: List[List[int]]) -> int:
        n = len(nums)
        m = len(queries)

        def can(k: int) -> bool:
            # Check if every index can reach exactly nums[i]
            # using values from the first k queries that cover i.
            for i, target in enumerate(nums):
                if target == 0:
                    continue

                bits = 1  # bit s is 1 iff sum s is reachable
                mask = (1 << (target + 1)) - 1

                for j in range(k):
                    l, r, val = queries[j]
                    if l <= i <= r:
                        bits |= (bits << val)
                        bits &= mask  # keep only sums up to target

                if ((bits >> target) & 1) == 0:
                    return False

            return True

        if can(0):
            return 0
        if not can(m):
            return -1

        lo, hi = 1, m
        while lo < hi:
            mid = (lo + hi) // 2
            if can(mid):
                hi = mid
            else:
                lo = mid + 1

        return lo

