from heapq import heappush, heappop

class Solution:
    def minOperations(self, n: int, m: int) -> int:
        d = len(str(n))
        if len(str(m)) != d:
            return -1

        limit = 10 ** d

        # Sieve of Eratosthenes: prime[x] == True iff x is prime.
        prime = [True] * limit
        if limit > 0:
            prime[0] = False
        if limit > 1:
            prime[1] = False

        p = 2
        while p * p < limit:
            if prime[p]:
                for x in range(p * p, limit, p):
                    prime[x] = False
            p += 1

        # n and m themselves must be non-prime.
        if prime[n] or prime[m]:
            return -1

        # 10^pos for each digit position (0 = units, 1 = tens, ...).
        pow10 = [1] * d
        for i in range(1, d):
            pow10[i] = pow10[i - 1] * 10

        # Dijkstra on states [0, 10^d - 1].
        # Moving to neighbor y adds cost y (start cost includes n).
        INF = 10**30
        dist = [INF] * limit
        dist[n] = n
        pq = [(n, n)]  # (cost, value)

        while pq:
            cost, x = heappop(pq)
            if cost != dist[x]:
                continue
            if x == m:
                return cost

            for pos in range(d):
                place = pow10[pos]
                digit = (x // place) % 10

                if digit < 9:
                    y = x + place
                    if not prime[y]:
                        nc = cost + y
                        if nc < dist[y]:
                            dist[y] = nc
                            heappush(pq, (nc, y))

                if digit > 0:
                    y = x - place
                    if not prime[y]:
                        nc = cost + y
                        if nc < dist[y]:
                            dist[y] = nc
                            heappush(pq, (nc, y))

        return -1

