class Solution:
    def beautifulSplits(self, nums: List[int]) -> int:
        n = len(nums)
        if n < 3:
            return 0

        # z[i] = LCP(nums[0:], nums[i:])
        z = [0] * n
        l = r = 0
        for i in range(1, n):
            if i <= r:
                z[i] = min(r - i + 1, z[i - l])
            while i + z[i] < n and nums[z[i]] == nums[i + z[i]]:
                z[i] += 1
            if i + z[i] - 1 > r:
                l, r = i, i + z[i] - 1

        ans = 0
        next_row = [0] * (n + 1)

        for i in range(n - 2, 0, -1):
            curr = [0] * (n + 1)
            ai = nums[i]
            a_ok = z[i] >= i
            two_i = i * 2

            for j in range(n - 1, i, -1):
                if ai == nums[j]:
                    curr[j] = next_row[j + 1] + 1

                good = False
                # nums1 is prefix of nums2
                if a_ok and j >= two_i:
                    good = True
                else:
                    # nums2 is prefix of nums3
                    # len2 = j-i must be <= len3 = n-j  => 2*j - i <= n
                    if 2 * j - i <= n and curr[j] >= (j - i):
                        good = True
                if good:
                    ans += 1

            next_row = curr

        return ans

