from typing import List

class Solution:
    def maxRemovals(self, source: str, pattern: str, targetIndices: List[int]) -> int:
        n, m = len(source), len(pattern)

        removable = [False] * n
        for idx in targetIndices:
            removable[idx] = True

        NEG = -10**9
        dp = [NEG] * (m + 1)
        dp[0] = 0

        for i, ch in enumerate(source):
            ndp = [NEG] * (m + 1)
            can_remove = removable[i]

            for j in range(m + 1):
                cur = dp[j]
                if cur == NEG:
                    continue

                # Option 1: do not use this char for matching pattern[j].
                if can_remove:
                    # If removable, we can delete it and gain one operation.
                    if cur + 1 > ndp[j]:
                        ndp[j] = cur + 1
                else:
                    # If not removable, it must stay.
                    if cur > ndp[j]:
                        ndp[j] = cur

                # Option 2: keep this char and match next pattern character.
                if j < m and ch == pattern[j]:
                    if cur > ndp[j + 1]:
                        ndp[j + 1] = cur

            dp = ndp

        return dp[m]

