from typing import List

class Solution:
    def minCost(self, n: int, cost: List[List[int]]) -> int:
        m = n // 2
        INF = 10**30

        # Valid (left_color, right_color) assignments for each mirrored pair.
        states = [(a, b) for a in range(3) for b in range(3) if a != b]  # 6 states

        # Base: outermost pair (0, n-1)
        dp = [0] * 6
        for s, (a, b) in enumerate(states):
            dp[s] = cost[0][a] + cost[n - 1][b]

        # Process pairs from outside to inside.
        for i in range(1, m):
            ndp = [INF] * 6
            for ns, (a, b) in enumerate(states):
                pair_cost = cost[i][a] + cost[n - 1 - i][b]
                best = INF
                for ps, (pa, pb) in enumerate(states):
                    # Adjacent constraints on both sides.
                    if a != pa and b != pb:
                        cand = dp[ps] + pair_cost
                        if cand < best:
                            best = cand
                ndp[ns] = best
            dp = ndp

        return min(dp)

