class Solution:
    def countOfSubstrings(self, word: str, k: int) -> int:
        vowels = {'a': 0, 'e': 1, 'i': 2, 'o': 3, 'u': 4}

        def at_most(K: int) -> int:
            if K < 0:
                return 0

            last = [-1] * 5          # last seen index for each vowel
            left = 0                 # left bound for window with consonants <= K
            consonants = 0
            total = 0

            for right, ch in enumerate(word):
                idx = vowels.get(ch, -1)
                if idx != -1:
                    last[idx] = right
                else:
                    consonants += 1

                while consonants > K:
                    if word[left] not in vowels:
                        consonants -= 1
                    left += 1

                # To contain all vowels, start must be <= min(last seen vowel index)
                min_last_vowel = min(last)
                if min_last_vowel >= left:
                    total += min_last_vowel - left + 1

            return total

        # exactly k = at most k - at most (k - 1)
        return at_most(k) - at_most(k - 1)

