                x2, y2 = pts[j]
                if x1 >= x2 or y1 >= y2:
                    continue
                # Check four corners exist
                if (x1, y2) not in s or (x2, y1) not in s:
                    continue

                corners = {(x1, y1), (x1, y2), (x2, y1), (x2, y2)}
                ok = True
                for x, y in pts:
                    if x1 <= x <= x2 and y1 <= y <= y2 and (x, y) not in corners:
                        ok = False
                        break
                if ok:
                    best = max(best, (x2 - x1) * (y2 - y1))

        return best

