from typing import List

class Solution:
    def maxRectangleArea(self, points: List[List[int]]) -> int:
        pts = [tuple(p) for p in points]
        point_set = set(pts)
        n = len(pts)
        best = -1

        for i in range(n):
            x1, y1 = pts[i]
            for j in range(n):
                x2, y2 = pts[j]

                # Treat (x1, y1) as bottom-left and (x2, y2) as top-right
                if x1 >= x2 or y1 >= y2:
                    continue

                # All four corners must exist
                if (x1, y2) not in point_set or (x2, y1) not in point_set:
                    continue

                corners = {(x1, y1), (x1, y2), (x2, y1), (x2, y2)}
                valid = True

                # No extra point allowed inside or on border
                for x, y in pts:
                    if x1 <= x <= x2 and y1 <= y <= y2 and (x, y) not in corners:
                        valid = False
                        break

                if valid:
                    best = max(best, (x2 - x1) * (y2 - y1))

        return best
